def tem_par_soma(arr, alvo):
    vistos = {}  # valor -> indice

    for i, num in enumerate(arr):
        complemento = alvo - num
        if complemento in vistos:
            return [vistos[complemento], i]
        vistos[num] = i

    return None

# Uso
print(tem_par_soma([2, 7, 11, 15], 9))  # [0, 1]

from collections import Counter

def contar_frequencia(arr):
    # Counter cria um dicionario: elemento -> contagem
    return dict(Counter(arr))

# Uso
freq = contar_frequencia([1, 2, 2, 3, 3, 3])
print(freq)  # {1: 1, 2: 2, 3: 3}

# Acessar frequencia especifica
print(freq[2])  # 2

def dois_numeros_soma(arr, alvo):
    esquerda, direita = 0, len(arr) - 1

    while esquerda < direita:
        soma_atual = arr[esquerda] + arr[direita]

        if soma_atual == alvo:
            return [esquerda, direita]
        elif soma_atual < alvo:
            esquerda += 1  # Precisa de numero maior
        else:
            direita -= 1  # Precisa de numero menor

    return None

# Uso
arr = [2, 7, 11, 15]
print(dois_numeros_soma(arr, 9))  # [0, 1]

class Pilha:
    def __init__(self):
        self.itens = []

    def push(self, item):
        """Adiciona item ao topo. O(1)"""
        self.itens.append(item)

    def pop(self):
        """Remove e retorna item do topo. O(1)"""
        if self.is_empty():
            raise IndexError("Pilha vazia")
        return self.itens.pop()

    def peek(self):
        """Retorna item do topo sem remover. O(1)"""
        if self.is_empty():
            raise IndexError("Pilha vazia")
        return self.itens[-1]

    def is_empty(self):
        """Verifica se pilha esta vazia. O(1)"""
        return len(self.itens) == 0

    def tamanho(self):
        """Retorna numero de elementos. O(1)"""
        return len(self.itens)

# Uso
pilha = Pilha()
pilha.push(10)
pilha.push(20)
print(pilha.pop())    # 20
print(pilha.peek())   # 10

def busca_binaria(arr, alvo):
    esquerda, direita = 0, len(arr) - 1

    while esquerda <= direita:
        meio = (esquerda + direita) // 2

        if arr[meio] == alvo:
            return meio  # Encontrado
        elif arr[meio] < alvo:
            esquerda = meio + 1  # Procura na metade direita
        else:
            direita = meio - 1   # Procura na metade esquerda

    return -1  # Nao encontrado

# Uso
arr = [1, 3, 5, 7, 9, 11, 13]
print(busca_binaria(arr, 7))   # 3 (indice)
print(busca_binaria(arr, 4))   # -1

from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

# Uso
print(fibonacci(10))  # 55
print(fibonacci(50))  # 12586269025
